CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, title TEXT, model TEXT, preview TEXT, message_count INTEGER NOT NULL, profile_id TEXT, pinned BOOLEAN NOT NULL, archived BOOLEAN NOT NULL, folder_id TEXT, pin_sort_order INTEGER, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, reasoning_effort TEXT, cwd TEXT, repo TEXT, non_interactive BOOLEAN NOT NULL DEFAULT 0, rules_import TEXT);
CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL, role TEXT NOT NULL, content TEXT NOT NULL, timestamp TEXT, tool_call_id TEXT, provider_id TEXT, prompt_tokens INTEGER, completion_tokens INTEGER, total_tokens INTEGER, cache_read_tokens INTEGER, cache_write_tokens INTEGER, context_window INTEGER, elapsed_ms INTEGER, attachments TEXT, reasoning TEXT, tool_calls TEXT, translation TEXT, thinking TEXT);
CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY, slug TEXT UNIQUE, name TEXT NOT NULL, icon TEXT, environment TEXT NOT NULL, container_id TEXT, persona TEXT, location_aware BOOLEAN NOT NULL, pinned_limit INTEGER NOT NULL, sort_order INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS folders (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL, name TEXT NOT NULL, sort_order INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS scheduled_tasks (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL, session_id TEXT, name TEXT NOT NULL, trigger_kind TEXT NOT NULL, trigger_type TEXT NOT NULL, cron_expression TEXT, run_at TEXT, script_path TEXT, script_inline TEXT, needs_network BOOLEAN NOT NULL, timeout_secs INTEGER NOT NULL, approved BOOLEAN NOT NULL, enabled BOOLEAN NOT NULL, last_run_at TEXT, last_run_status TEXT, last_run_output TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, webhook_signature_secret TEXT, webhook_signature_header TEXT, word TEXT);
CREATE TABLE IF NOT EXISTS scheduled_task_runs (id TEXT PRIMARY KEY, task_id TEXT NOT NULL, profile_id TEXT NOT NULL, session_id TEXT, invocation_kind TEXT NOT NULL, status TEXT NOT NULL, output TEXT, started_at TEXT NOT NULL, finished_at TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS push_subscriptions (id TEXT PRIMARY KEY, endpoint TEXT NOT NULL, p256dh TEXT NOT NULL, auth TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profile_memories (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL, memory_type TEXT NOT NULL, content TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profile_memory_jobs (profile_id TEXT PRIMARY KEY, dirty BOOLEAN NOT NULL, last_processed_at TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profile_container_mounts (profile_id TEXT NOT NULL, ordinal INTEGER NOT NULL, host_path TEXT NOT NULL, container_path TEXT NOT NULL, access TEXT NOT NULL, PRIMARY KEY (profile_id, ordinal));
CREATE TABLE IF NOT EXISTS message_permission_requests (message_id INTEGER PRIMARY KEY, request_id TEXT NOT NULL, mode TEXT NOT NULL, script TEXT NOT NULL, reading TEXT);
CREATE TABLE IF NOT EXISTS message_permission_responses (message_id INTEGER PRIMARY KEY, request_id TEXT NOT NULL, approved BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS message_workspace_requests (message_id INTEGER PRIMARY KEY, request_id TEXT NOT NULL, path TEXT NOT NULL, reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS message_workspace_responses (message_id INTEGER PRIMARY KEY, request_id TEXT NOT NULL, approved BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS message_ask_user_requests (message_id INTEGER PRIMARY KEY, request_id TEXT NOT NULL, word TEXT);
CREATE TABLE IF NOT EXISTS message_ask_user_request_questions (message_id INTEGER NOT NULL, ordinal INTEGER NOT NULL, section TEXT NOT NULL, question TEXT NOT NULL, multi_select BOOLEAN NOT NULL, PRIMARY KEY (message_id, ordinal));
CREATE TABLE IF NOT EXISTS message_ask_user_request_options (message_id INTEGER NOT NULL, question_ordinal INTEGER NOT NULL, option_ordinal INTEGER NOT NULL, value TEXT NOT NULL, PRIMARY KEY (message_id, question_ordinal, option_ordinal));
CREATE TABLE IF NOT EXISTS message_ask_user_responses (message_id INTEGER PRIMARY KEY, request_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS message_ask_user_response_answers (message_id INTEGER NOT NULL, ordinal INTEGER NOT NULL, section TEXT NOT NULL, answer_kind TEXT NOT NULL, custom_text TEXT, PRIMARY KEY (message_id, ordinal));
CREATE TABLE IF NOT EXISTS message_ask_user_response_selected_options (message_id INTEGER NOT NULL, answer_ordinal INTEGER NOT NULL, option_ordinal INTEGER NOT NULL, value TEXT NOT NULL, PRIMARY KEY (message_id, answer_ordinal, option_ordinal));
CREATE TABLE IF NOT EXISTS session_pending_message_entries (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL, delivery_mode TEXT NOT NULL, content TEXT NOT NULL, hidden_context_xml TEXT, created_at TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', claimed_run_id TEXT, claim_error TEXT);
CREATE TABLE IF NOT EXISTS session_pending_message_attachments (message_id INTEGER NOT NULL, ordinal INTEGER NOT NULL, attachment_id TEXT NOT NULL, name TEXT NOT NULL, attachment_type TEXT NOT NULL, url TEXT NOT NULL, text_content TEXT, PRIMARY KEY (message_id, ordinal));
CREATE TABLE IF NOT EXISTS session_pending_ask_user_requests_v2 (request_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, created_at TEXT NOT NULL, blocking BOOLEAN NOT NULL DEFAULT 1, word TEXT);
CREATE TABLE IF NOT EXISTS session_pending_ask_user_questions_v2 (request_id TEXT NOT NULL, ordinal INTEGER NOT NULL, section TEXT NOT NULL, question TEXT NOT NULL, multi_select BOOLEAN NOT NULL, secret_name TEXT, secret_scope TEXT, PRIMARY KEY (request_id, ordinal));
CREATE TABLE IF NOT EXISTS session_pending_ask_user_question_options_v2 (request_id TEXT NOT NULL, question_ordinal INTEGER NOT NULL, option_ordinal INTEGER NOT NULL, value TEXT NOT NULL, PRIMARY KEY (request_id, question_ordinal, option_ordinal));
CREATE TABLE IF NOT EXISTS context_debug_snapshot_headers (session_id TEXT PRIMARY KEY, timestamp TEXT NOT NULL, model TEXT NOT NULL, provider_id TEXT NOT NULL, prompt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS context_debug_snapshot_prompt_attachments (session_id TEXT NOT NULL, ordinal INTEGER NOT NULL, url TEXT NOT NULL, PRIMARY KEY (session_id, ordinal));
CREATE TABLE IF NOT EXISTS context_debug_snapshot_messages (session_id TEXT NOT NULL, ordinal INTEGER NOT NULL, role TEXT NOT NULL, content TEXT NOT NULL, tool_call_id TEXT, PRIMARY KEY (session_id, ordinal));
CREATE TABLE IF NOT EXISTS context_debug_snapshot_message_attachments (session_id TEXT NOT NULL, message_ordinal INTEGER NOT NULL, attachment_ordinal INTEGER NOT NULL, url TEXT NOT NULL, PRIMARY KEY (session_id, message_ordinal, attachment_ordinal));
CREATE TABLE IF NOT EXISTS context_debug_snapshot_message_tool_calls (session_id TEXT NOT NULL, message_ordinal INTEGER NOT NULL, tool_call_ordinal INTEGER NOT NULL, name TEXT NOT NULL, PRIMARY KEY (session_id, message_ordinal, tool_call_ordinal));
CREATE TABLE IF NOT EXISTS notification_mailbox (id TEXT PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, session_id TEXT, status TEXT NOT NULL, sent_count INTEGER NOT NULL, last_error TEXT, delivered_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, profile_id TEXT);
CREATE TABLE IF NOT EXISTS request_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL, timestamp TEXT NOT NULL, model TEXT NOT NULL, provider_id TEXT NOT NULL, prompt_tokens INTEGER, completion_tokens INTEGER, total_tokens INTEGER, cache_read_tokens INTEGER, cache_write_tokens INTEGER, context_window INTEGER, elapsed_ms INTEGER NOT NULL, ok BOOLEAN NOT NULL, error TEXT);
CREATE TABLE IF NOT EXISTS network_access_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT, profile_id TEXT, source TEXT NOT NULL, mode TEXT NOT NULL, domain TEXT NOT NULL, port INTEGER NOT NULL, allowed BOOLEAN NOT NULL, reason TEXT, timestamp TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session_runtimes (session_id TEXT PRIMARY KEY, state TEXT NOT NULL, run_id TEXT, browser_takeover_active BOOLEAN NOT NULL, browser_takeover_alert_pending BOOLEAN NOT NULL, terminal_task_id TEXT, terminal_output_file TEXT, terminal_output_preview TEXT, terminal_input_notice TEXT, terminal_background_reason TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session_plans (session_id TEXT PRIMARY KEY, plan_state TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session_yolo (session_id TEXT PRIMARY KEY, enabled BOOLEAN NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session_pending_permissions (request_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, mode TEXT NOT NULL, script TEXT NOT NULL, created_at TEXT NOT NULL, agent_id TEXT);
CREATE TABLE IF NOT EXISTS session_pending_workspace (request_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, path TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_messages_session_id ON messages(session_id);
CREATE INDEX IF NOT EXISTS idx_messages_session_role ON messages(session_id, role);
CREATE INDEX IF NOT EXISTS idx_sessions_profile_id ON sessions(profile_id);
CREATE INDEX IF NOT EXISTS idx_sessions_archived ON sessions(archived, updated_at);
CREATE INDEX IF NOT EXISTS idx_folders_profile_id ON folders(profile_id);
CREATE INDEX IF NOT EXISTS idx_scheduled_tasks_profile ON scheduled_tasks(profile_id);
CREATE INDEX IF NOT EXISTS idx_profile_memories_profile ON profile_memories(profile_id, memory_type);
CREATE INDEX IF NOT EXISTS idx_profile_memory_jobs_dirty_updated_at ON profile_memory_jobs(dirty, updated_at);
CREATE INDEX IF NOT EXISTS idx_profile_container_mounts_profile ON profile_container_mounts(profile_id, ordinal);
CREATE INDEX IF NOT EXISTS idx_message_permission_requests_request_id ON message_permission_requests(request_id);
CREATE INDEX IF NOT EXISTS idx_message_permission_responses_request_id ON message_permission_responses(request_id);
CREATE INDEX IF NOT EXISTS idx_message_workspace_requests_request_id ON message_workspace_requests(request_id);
CREATE INDEX IF NOT EXISTS idx_message_workspace_responses_request_id ON message_workspace_responses(request_id);
CREATE INDEX IF NOT EXISTS idx_message_ask_user_requests_request_id ON message_ask_user_requests(request_id);
CREATE INDEX IF NOT EXISTS idx_message_ask_user_responses_request_id ON message_ask_user_responses(request_id);
CREATE INDEX IF NOT EXISTS idx_session_pending_message_entries_session_created ON session_pending_message_entries(session_id, created_at);

CREATE TABLE IF NOT EXISTS session_transcript_entries (session_id TEXT NOT NULL, seq INTEGER NOT NULL, message_blob BLOB NOT NULL, committed_at TEXT NOT NULL, PRIMARY KEY (session_id, seq));
CREATE INDEX IF NOT EXISTS idx_session_pending_message_attachments_message ON session_pending_message_attachments(message_id, ordinal);
CREATE INDEX IF NOT EXISTS idx_session_pending_ask_user_requests_v2_session ON session_pending_ask_user_requests_v2(session_id);
CREATE INDEX IF NOT EXISTS idx_context_debug_snapshot_headers_timestamp ON context_debug_snapshot_headers(timestamp);
CREATE INDEX IF NOT EXISTS idx_notification_mailbox_status_created_at ON notification_mailbox(status, created_at);
CREATE INDEX IF NOT EXISTS idx_request_logs_timestamp ON request_logs(timestamp);
CREATE INDEX IF NOT EXISTS idx_request_logs_session_timestamp ON request_logs(session_id, timestamp);
CREATE INDEX IF NOT EXISTS idx_network_access_logs_timestamp ON network_access_logs(timestamp);
CREATE INDEX IF NOT EXISTS idx_network_access_logs_session ON network_access_logs(session_id, timestamp);
CREATE INDEX IF NOT EXISTS idx_session_pending_permissions_session ON session_pending_permissions(session_id);
CREATE INDEX IF NOT EXISTS idx_session_pending_workspace_session ON session_pending_workspace(session_id);
CREATE TABLE IF NOT EXISTS message_tool_cards (session_id TEXT NOT NULL, call_id TEXT NOT NULL, card TEXT NOT NULL, PRIMARY KEY (session_id, call_id));
CREATE TABLE IF NOT EXISTS issue_projects (id INTEGER PRIMARY KEY, repo_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS issues (id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL, number INTEGER NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, state TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (project_id, number));
CREATE TABLE IF NOT EXISTS issue_labels (id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL, name TEXT NOT NULL, UNIQUE (project_id, name));
CREATE TABLE IF NOT EXISTS issue_label_assignments (issue_id INTEGER NOT NULL, label_id INTEGER NOT NULL, PRIMARY KEY (issue_id, label_id));
CREATE TABLE IF NOT EXISTS issue_comments (id INTEGER PRIMARY KEY AUTOINCREMENT, issue_id INTEGER NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS issue_relations (issue_id INTEGER NOT NULL, related_issue_id INTEGER NOT NULL, kind TEXT NOT NULL, PRIMARY KEY (issue_id, related_issue_id, kind));
CREATE INDEX IF NOT EXISTS idx_issues_project ON issues(project_id, state, number);
CREATE INDEX IF NOT EXISTS idx_issue_labels_project ON issue_labels(project_id);
CREATE INDEX IF NOT EXISTS idx_issue_label_assignments_label ON issue_label_assignments(label_id);
CREATE INDEX IF NOT EXISTS idx_issue_comments_issue ON issue_comments(issue_id);
CREATE INDEX IF NOT EXISTS idx_issue_relations_issue ON issue_relations(issue_id, kind);
CREATE INDEX IF NOT EXISTS idx_issue_relations_related ON issue_relations(related_issue_id, kind);
CREATE TABLE IF NOT EXISTS profile_remote_servers (profile_id TEXT NOT NULL, ssh_server_name TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, PRIMARY KEY (profile_id, ssh_server_name));
CREATE INDEX IF NOT EXISTS idx_profile_remote_servers_profile ON profile_remote_servers(profile_id, sort_order);
CREATE TABLE IF NOT EXISTS repo_usage (worktree TEXT PRIMARY KEY, last_used_at INTEGER NOT NULL, use_count INTEGER NOT NULL, owner_repo TEXT);
CREATE TABLE IF NOT EXISTS issue_search_docs (collection TEXT NOT NULL, number INTEGER NOT NULL, title TEXT NOT NULL, state TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (collection, number));
PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS prs (id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL, number INTEGER NOT NULL, session_id TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', state TEXT NOT NULL, branch TEXT NOT NULL, base_sha TEXT NOT NULL, head_sha TEXT, backend TEXT NOT NULL, external_number INTEGER, auto_merge BOOLEAN NOT NULL DEFAULT 1, issue_number INTEGER, merge_commit_sha TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, merged_at TEXT, UNIQUE (project_id, number));
CREATE INDEX IF NOT EXISTS idx_prs_session ON prs(session_id);
CREATE INDEX IF NOT EXISTS idx_prs_project_state ON prs(project_id, state);
CREATE TABLE IF NOT EXISTS pr_events (id INTEGER PRIMARY KEY AUTOINCREMENT, pr_id INTEGER NOT NULL, kind TEXT NOT NULL, session_id TEXT NOT NULL, agent_id TEXT NOT NULL, message_id INTEGER, detail TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_pr_events_pr ON pr_events(pr_id);
CREATE TABLE IF NOT EXISTS issue_provenance (id INTEGER PRIMARY KEY AUTOINCREMENT, backend TEXT NOT NULL, repository TEXT NOT NULL, issue_number INTEGER NOT NULL, comment_id INTEGER, action TEXT NOT NULL, detail TEXT, session_id TEXT NOT NULL, agent TEXT NOT NULL, tool_call_id TEXT, recorded_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_issue_provenance_issue ON issue_provenance(backend, repository, issue_number);
CREATE TABLE IF NOT EXISTS session_repo_clones (session_id TEXT NOT NULL, repo_key TEXT NOT NULL, dir TEXT NOT NULL, source TEXT NOT NULL, local BOOLEAN NOT NULL, base_sha TEXT, PRIMARY KEY (session_id, repo_key));
CREATE TABLE IF NOT EXISTS session_intervals (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL, kind TEXT NOT NULL, start_ms INTEGER NOT NULL, end_ms INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_session_intervals_session ON session_intervals(session_id);
CREATE TABLE IF NOT EXISTS prompt_cache_routes (session_id TEXT NOT NULL, provider_id TEXT NOT NULL, model TEXT NOT NULL, observed_at_ms INTEGER NOT NULL, cache_read_tokens INTEGER NOT NULL, cache_write_tokens INTEGER, chain BLOB NOT NULL, PRIMARY KEY (session_id, provider_id, model));
CREATE TABLE IF NOT EXISTS cache_misses (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL, timestamp TEXT NOT NULL, model TEXT NOT NULL, provider_id TEXT NOT NULL, cause TEXT NOT NULL, missed_tokens INTEGER NOT NULL, read_tokens INTEGER NOT NULL, gap_ms INTEGER NOT NULL, diverged_kind TEXT, diverged_index INTEGER, compacted BOOLEAN NOT NULL, reassembled BOOLEAN NOT NULL, agent_rebuilt BOOLEAN NOT NULL, model_switched BOOLEAN NOT NULL);
CREATE INDEX IF NOT EXISTS idx_cache_misses_session_timestamp ON cache_misses(session_id, timestamp);
CREATE TABLE IF NOT EXISTS sleep_log (id INTEGER PRIMARY KEY AUTOINCREMENT, slept_at_ms INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS daemon_runs (id INTEGER PRIMARY KEY CHECK (id = 1), process_session INTEGER NOT NULL, stopped BOOLEAN NOT NULL, started_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session_background_live (session_id TEXT PRIMARY KEY, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session_daemon_exit_alerts (session_id TEXT PRIMARY KEY, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ci_jobs (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL, pr_id INTEGER NOT NULL, session_id TEXT NOT NULL, source TEXT NOT NULL, external_id INTEGER NOT NULL, run_id INTEGER NOT NULL, workflow TEXT NOT NULL, name TEXT NOT NULL, conclusion TEXT NOT NULL, started_at_ms INTEGER NOT NULL, duration_secs INTEGER NOT NULL, recorded_at_ms INTEGER NOT NULL, UNIQUE (project_id, source, external_id));
CREATE INDEX IF NOT EXISTS idx_ci_jobs_pr ON ci_jobs(pr_id);
CREATE INDEX IF NOT EXISTS idx_ci_jobs_name ON ci_jobs(project_id, workflow, name, started_at_ms);
CREATE TABLE IF NOT EXISTS ci_steps (job_id INTEGER NOT NULL, ordinal INTEGER NOT NULL, name TEXT NOT NULL, duration_secs INTEGER NOT NULL, PRIMARY KEY (job_id, ordinal));
CREATE TABLE IF NOT EXISTS ci_tests (job_id INTEGER NOT NULL, ordinal INTEGER NOT NULL, kind TEXT NOT NULL, name TEXT NOT NULL, duration_ms INTEGER NOT NULL, PRIMARY KEY (job_id, ordinal));
CREATE TABLE IF NOT EXISTS ci_baselines (project_id INTEGER NOT NULL, workflow TEXT NOT NULL, name TEXT NOT NULL, median_secs INTEGER NOT NULL, samples INTEGER NOT NULL, updated_at_ms INTEGER NOT NULL, PRIMARY KEY (project_id, workflow, name));
CREATE TABLE IF NOT EXISTS ci_pr_runs (pr_id INTEGER PRIMARY KEY, queue_wait_secs INTEGER NOT NULL, run_secs INTEGER NOT NULL, recorded_at_ms INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ci_findings (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL, pr_id INTEGER NOT NULL, head_sha TEXT NOT NULL, warning TEXT NOT NULL, alert TEXT NOT NULL, alerted BOOLEAN NOT NULL DEFAULT 0, created_at_ms INTEGER NOT NULL, UNIQUE (pr_id, head_sha));
CREATE INDEX IF NOT EXISTS idx_ci_findings_session ON ci_findings(session_id, id);
CREATE TABLE IF NOT EXISTS session_names (name TEXT PRIMARY KEY);
CREATE UNIQUE INDEX IF NOT EXISTS idx_session_pending_ask_user_requests_v2_word ON session_pending_ask_user_requests_v2(session_id, word) WHERE word IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_message_ask_user_requests_word ON message_ask_user_requests(word) WHERE word IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_scheduled_tasks_word ON scheduled_tasks(session_id, word) WHERE word IS NOT NULL;
CREATE TABLE IF NOT EXISTS pr_check_state (pr_id INTEGER PRIMARY KEY, head_sha TEXT NOT NULL, rollup TEXT NOT NULL, unreadable BOOLEAN NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS pr_check_alerts (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL, pr_id INTEGER NOT NULL, text TEXT NOT NULL, alerted BOOLEAN NOT NULL DEFAULT 0, created_at_ms INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_pr_check_alerts_session ON pr_check_alerts(session_id, alerted);
